export interface KeychronKeyShape {
  row: number;
  col: number;
  /** Position of the key's top-left corner, in key widths. */
  x: number;
  y: number;
  w: number;
  h: number;
  /** Degrees clockwise around (`rx`, `ry`); 0 for most keys. */
  rotation: number;
  rx: number;
  ry: number;
  /** Rotary encoder index when this position is a knob, else null. */
  encoder: number | null;
}

export interface KeychronLayout {
  /** Overall size in key widths. */
  width: number;
  height: number;
  keys: readonly KeychronKeyShape[];
}

const cache = new Map<number, KeychronLayout>();

/** The physical layout of a catalogued Hall-effect board, or null for an unknown product id. */
export function keychronLayoutFor(productId: number): KeychronLayout | null {
  const cached = cache.get(productId);
  if (cached) return cached;
  const index = LAYOUT_BY_PRODUCT[productId];
  const raw = index === undefined ? undefined : LAYOUTS[index];
  if (!raw) return null;
  const layout: KeychronLayout = {
    width: raw[0],
    height: raw[1],
    keys: raw[2].map(([row, col, x, y, w, h, rotation, rx, ry, encoder]) => ({
      row, col, x, y, w, h, rotation, rx, ry, encoder: encoder < 0 ? null : encoder,
    })),
  };
  cache.set(productId, layout);
  return layout;
}
